// 50 test leads for the Telegram prototype.
//
// `profile` is what gets saved in customer_leads (what the bot "already knows").
// `messages` is what this person would type to the bot, in order.
// `expect` is what a good reply looks like; the eval suite asserts on the behaviour,
// not on exact wording. `shortlist` entries are matched against property locations
// when seeding, so no property IDs are hard-coded.
//
// Live inventory these were written against (20 listings, checked 2026-09-30):
//   residential: Anna Nagar West 4BHK 4.8Cr | Navalur OMR 2BHK 62L (under construction)
//     | Alwarpet bungalow (price on request) | Uthandi ECR 5BHK villa 9.5Cr
//     | East Tambaram 1BHK 28L | Velachery multi-family house 2.1Cr
//     | Besant Nagar 4BHK penthouse 6.5Cr (SOLD)
//   plot: Medavakkam villa plot 84L | Poonamallee institutional land 72Cr
//   farmland: Urapakkam/Chengalpattu 1.65Cr
//   commercial: Sholinganallur OMR office 24.5Cr | Mylapore shop 1.85Cr
//     | T. Nagar showroom 45Cr (RESERVED) | Perungudi cloud kitchen 1.35Cr
//   commercial_redevelopment: Triplicane 32Cr
//   hospitality: Mamallapuram resort 160Cr | Guindy boutique hotel 19Cr
//   industrial: Ambattur shed (no price) | Sriperumbudur warehouse 52Cr | Koyambedu cold storage 11.5Cr

const L = (n) => Math.round(n * 100000);
const Cr = (n) => Math.round(n * 10000000);

const point = (type, text, confidence = 0.9) => ({ type, text, confidence });

function lead(id, name, stage, tags, profile, messages, expect) {
  return {
    id: `test:${id}`,
    name,
    stage,
    tags,
    profile: {
      locations: [],
      categories: [],
      mustHaves: [],
      dealBreakers: [],
      keyPoints: [],
      shortlist: [],
      ...profile
    },
    messages,
    expect
  };
}

